-- Store avatar images inline so the shop does not depend on /avatars/*.svg
-- static files (those 404 on the deployed site until public assets are shipped).

UPDATE public.avatars
SET image_url = 'data:image/svg+xml;base64,'
WHERE name = 'Pawn'
   OR image_url IN ('/avatars/pawn.svg', 'pawn.svg');

UPDATE public.avatars
SET image_url = 'data:image/svg+xml;base64,'
WHERE name = 'Bishop'
   OR image_url IN ('/avatars/bishop.svg', 'bishop.svg');

