   OR image_url IN ('/avatars/knight.svg', 'knight.svg');

UPDATE public.avatars
SET image_url = 'data:image/svg+xml;base64,'
WHERE name = 'Rook'
   OR image_url IN ('/avatars/rook.svg', 'rook.svg');

UPDATE public.avatars
SET image_url = 'data:image/svg+xml;base64,'
WHERE name = 'Queen'
   OR image_url IN ('/avatars/queen.svg', 'queen.svg');

UPDATE public.avatars
SET image_url = 'data:image/svg+xml;base64,'
